import { useState, useEffect } from "react";

function App() {

  const [score, setScore] = useState(0)

  const addScore = () => {
    setScore(score + 1);
  }

  const upgrade = () => {
    switch(score) {
      case(score === 60):
        console.log(1);
        break;
      default:
        break;
    }
  }

  useEffect(() => {
    upgrade()
  }, [upgrade]);

  return (
    <div className="Container">
      <h1>{score}</h1>

      <button onClick={addScore}>+</button>
    </div>
  );
}

export default App;
